// The plate-layout example's transpile output: developer-owned generated source
// and the tests that drive it. This example exercises many records from one
// request (Reference §14, `for each`): a design whose submission lays out
// containers × replicates containers and the wells under each, from one rule
// firing. Regenerated by `gradle generate`.
plugins {
    kotlin("jvm")
}

group = "velle"

repositories {
    mavenCentral()
}

dependencies {
    implementation(project(":compiler"))
    testImplementation(kotlin("test"))
    testImplementation(project(":stores:sqlite")) // the flows re-run over real storage
}

tasks.test {
    useJUnitPlatform()
}

tasks.register<JavaExec>("generate") {
    description = "Regenerate the PlateLayout typed surface and executable specs from platelayout.velle"
    classpath = sourceSets["main"].runtimeClasspath
    mainClass.set("velle.GenerateKt")
    args("../platelayout.velle", "PlateLayout")
}

kotlin {
    compilerOptions {
        jvmTarget.set(org.jetbrains.kotlin.gradle.dsl.JvmTarget.JVM_21)
    }
}

java {
    sourceCompatibility = JavaVersion.VERSION_21
    targetCompatibility = JavaVersion.VERSION_21
}
